<?php $active_menu='payroll';$active_submenu='salary_structures';include 'header.php';require_once __DIR__.'/../foundation.php';oecrm_require_permission($conn,'salary_structures','view');$companyId=oecrm_current_company_id($conn);$flash='';if($_SERVER['REQUEST_METHOD']==='POST'){oecrm_require_csrf();oecrm_require_permission($conn,'salary_structures','edit');$id=(int)$_POST['id'];$gross=(float)$_POST['gross_salary'];$basic=(float)$_POST['basic_salary'];$hra=(float)$_POST['hra'];$special=(float)$_POST['special_allowance'];$other=(float)$_POST['other_allowance'];$pt=isset($_POST['professional_tax_enabled'])?1:0;$retType=$_POST['retention_type'];$ret=(float)$_POST['retention_value'];$stmt=mysqli_prepare($conn,'UPDATE salary_structures SET gross_salary=?,basic_salary=?,hra=?,special_allowance=?,other_allowance=?,professional_tax_enabled=?,retention_type=?,retention_value=? WHERE id=? AND company_id=?');mysqli_stmt_bind_param($stmt,'dddddisdii',$gross,$basic,$hra,$special,$other,$pt,$retType,$ret,$id,$companyId);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$employeeId=(int)$_POST['employee_id'];$salary=(string)$gross;$stmt=mysqli_prepare($conn,'UPDATE employeestbl SET salary=? WHERE id=? AND company_id=?');mysqli_stmt_bind_param($stmt,'sii',$salary,$employeeId,$companyId);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);oecrm_audit($conn,'salary_structures','update','salary_structure',$id,'Salary structure updated',null,$_POST);$flash='Salary structure updated.';}$list=mysqli_query($conn,'SELECT s.*,e.employeeCode,e.name,e.designation FROM salary_structures s JOIN employeestbl e ON e.id=s.employee_id WHERE s.company_id='.(int)$companyId.' AND s.status=1 ORDER BY e.name');?>
<div id="page-wrapper" class="compact-admin-page payroll-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?><div class="panel panel-default"><div class="panel-heading">Employee Salary Structures</div><div class="panel-body"><div class="salary-structure-grid"><?php while($s=mysqli_fetch_assoc($list)):?><form method="post" class="salary-structure-card"><?php echo oecrm_csrf_field();?><input type="hidden" name="id" value="<?php echo (int)$s['id'];?>"><input type="hidden" name="employee_id" value="<?php echo (int)$s['employee_id'];?>"><header><div><strong><?php echo oecrm_h($s['name']);?></strong><small><?php echo oecrm_h($s['employeeCode'].' · '.$s['designation']);?></small></div><span>?<?php echo number_format($s['gross_salary'],0);?></span></header><div class="salary-fields"><div><label>Gross</label><input type="number" step="0.01" class="form-control" name="gross_salary" value="<?php echo $s['gross_salary'];?>"></div><div><label>Basic</label><input type="number" step="0.01" class="form-control" name="basic_salary" value="<?php echo $s['basic_salary'];?>"></div><div><label>HRA</label><input type="number" step="0.01" class="form-control" name="hra" value="<?php echo $s['hra'];?>"></div><div><label>Special</label><input type="number" step="0.01" class="form-control" name="special_allowance" value="<?php echo $s['special_allowance'];?>"></div><div><label>Other</label><input type="number" step="0.01" class="form-control" name="other_allowance" value="<?php echo $s['other_allowance'];?>"></div><div><label>Retention</label><select class="form-control" name="retention_type"><?php foreach(['none','fixed','percent'] as $v):?><option <?php echo $s['retention_type']===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select></div><div><label>Retention Value</label><input type="number" step="0.01" class="form-control" name="retention_value" value="<?php echo $s['retention_value'];?>"></div></div><footer><label><input type="checkbox" name="professional_tax_enabled" <?php echo $s['professional_tax_enabled']?'checked':'';?>> Professional Tax</label><button class="btn btn-primary btn-sm"><i class="fa fa-save"></i> Save</button></footer></form><?php endwhile;?></div></div></div></div><?php include 'footer.php';?>